import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Private Rooms","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/private_rooms.md","filePath":"gameplay/private_rooms.md","lastUpdated":1790774905000}'),i={name:"gameplay/private_rooms.md"};function n(l,t,o,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="private-rooms" tabindex="-1">Private Rooms <a class="header-anchor" href="#private-rooms" aria-label="Permalink to &quot;Private Rooms&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>In Private Rooms players either play a normal Ranked Seed or they can choose a Set Seed. It is also possible to disable Seedtypes so players can practice the Seedtypes they want. There are 20+ Categories to choose from aside from the standard Any% Category and players can chooe which Rules to turn ON/OFF (QOL rules, experimental features and rules that make the game harder/easier(fairer).</p><h2 id="special-tiers" tabindex="-1">Special Tiers <a class="header-anchor" href="#special-tiers" aria-label="Permalink to &quot;Special Tiers&quot;">​</a></h2><p>Everyone can make a Private Room in the most basic form, but certain features require a <a href="https://store.mcsrranked.com/category/tiers" target="_blank" rel="noreferrer">Special Tier</a>. Here is specified what the different tiers can do in a Private Room.</p><h3 id="no-pickaxe" tabindex="-1">No Pickaxe <a class="header-anchor" href="#no-pickaxe" aria-label="Permalink to &quot;No Pickaxe&quot;">​</a></h3><ul><li>Max. 32 players</li><li>Toggle Rules ON/OFF</li><li>Run Command on World Join</li><li>Choose Category</li><li>Choose a Set Seed</li></ul><h3 id="stone-pickaxe" tabindex="-1">Stone Pickaxe <a class="header-anchor" href="#stone-pickaxe" aria-label="Permalink to &quot;Stone Pickaxe&quot;">​</a></h3><ul><li>Same as No Pickaxe</li><li>Solo Private Room</li><li>Choose Seedtype</li><li>Choose Bastiontype</li></ul><h3 id="iron-pickaxe" tabindex="-1">Iron Pickaxe <a class="header-anchor" href="#iron-pickaxe" aria-label="Permalink to &quot;Iron Pickaxe&quot;">​</a></h3><ul><li>Same as Stone Pickaxe</li><li>Max. 64 players</li><li>Choose a Custom Room Name</li><li>Play against Ranked Bot</li></ul><h3 id="diamond-pickaxe" tabindex="-1">Diamond Pickaxe <a class="header-anchor" href="#diamond-pickaxe" aria-label="Permalink to &quot;Diamond Pickaxe&quot;">​</a></h3><ul><li>Same as Iron Pickaxe</li><li>Request to Join Private Room option</li></ul><h2 id="rng-standardization" tabindex="-1">RNG Standardization <a class="header-anchor" href="#rng-standardization" aria-label="Permalink to &quot;RNG Standardization&quot;">​</a></h2><p>The standardizations listed below are relevant for some of the categories that can be chosen in a private room, see <a href="./rng">here</a> for the full list of standardizations.</p><ul><li>Rain/thunderstorm cycle is standardized <ul><li>Also thunderstorms are more frequent</li></ul></li><li>Phantoms spawn and cycle are standardized</li></ul><h2 id="game-rules" tabindex="-1">Game Rules <a class="header-anchor" href="#game-rules" aria-label="Permalink to &quot;Game Rules&quot;">​</a></h2><p>Going to Options &gt; Rules in a Private Room shows the game rules. Listed below are all the rules with their explanation and default setting.</p><table tabindex="0"><thead><tr><th>Rules</th><th>Explanation</th><th style="text-align:center;">  Default  <br>(ON/OFF)</th></tr></thead><tbody><tr><td>Disable Public Replay</td><td>Disables saving replay on the server.</td><td style="text-align:center;">OFF</td></tr><tr><td>Force Rejoin with Reconnection</td><td>If the player reconnects to the server after instance restart and without forfeiting or leaving the room, the player can continue playing in the room with the seed reset.</td><td style="text-align:center;">OFF</td></tr><tr><td>Use Player Ready System</td><td>Players in the room can toggle a ready status to indicate whether they are ready. Only the hosts can see which players are ready.</td><td style="text-align:center;">OFF</td></tr><tr><td>Standardized Portal Lit by Fire</td><td>(EXPERIMENTAL!) Standardizes the amount of time it takes for a portal to get lit.</td><td style="text-align:center;">OFF</td></tr><tr><td>Beginner Mode</td><td>Keep inventory is enabled and the players respawnpoint is set to the position the player was in when the last split changed.</td><td style="text-align:center;">OFF</td></tr><tr><td>Display Filtered Seed Type</td><td>Displays the seed type on the countdown screen. Not shown for set seeds or non-filtered seeds.</td><td style="text-align:center;">ON</td></tr><tr><td>Allow Use Cheat Commands</td><td>Allows the player to use all commands.</td><td style="text-align:center;">OFF</td></tr><tr><td>Use Filtered Seed</td><td>If you leave the world seed text input blank, you will be given a filtered random seed.</td><td style="text-align:center;">ON</td></tr><tr><td>Reduce Waiting Time</td><td>Reduces the timer on the countdown screen from 10 seconds to 5 seconds.</td><td style="text-align:center;">ON</td></tr><tr><td>Show Advancement Messages</td><td>When any player completes an advancement, their advancement message will be displayed.</td><td style="text-align:center;">ON</td></tr><tr><td>Show Advancement Only Once</td><td>Advancement messages will be displayed only once for each advancement, and will no longer be displayed if someone has already completed the same advancement.</td><td style="text-align:center;">OFF</td></tr><tr><td>Send World Reset Message</td><td>Sends a message to all players when a player resets the world.</td><td style="text-align:center;">OFF</td></tr><tr><td>IGT Mode</td><td>Changes the final time to use IGT instead of RTA. If the &#39;Waiting All Completion&#39; option is disabled, the player with the first completion will still win.</td><td style="text-align:center;">OFF</td></tr><tr><td>Modified Portal Behaviors</td><td>See <a href="./rng#player-portal-behaviors">here</a> for the modified Nether Portal Behavior.</td><td style="text-align:center;">ON</td></tr><tr><td>Remove Block Entities From Spawn</td><td>Removes all block entities from Dungeons, Ocean Ruins and Mineshafts around spawn.</td><td style="text-align:center;">ON</td></tr><tr><td>Generate Artificial Lava Pools</td><td>Artificially generated lava pools around villages and desert temples.</td><td style="text-align:center;">ON</td></tr><tr><td>Disable Mining Fatigue</td><td>Disables the mining fatigue effect from Elder Guardians.</td><td style="text-align:center;">ON</td></tr><tr><td>Modified Piglin Barters</td><td>See <a href="./rng#piglin-barters">here</a> for the modified Piglin Barters.</td><td style="text-align:center;">ON</td></tr><tr><td>No Monster Spawn in Bastion</td><td>Prevents Monsters from spawning in Bastion Remnants.</td><td style="text-align:center;">ON</td></tr><tr><td>Standardized Dragon Perch</td><td>See <a href="./rng#ender-dragon">here</a> for the details.</td><td style="text-align:center;">ON</td></tr><tr><td>Dragon Perch Immediately</td><td>The Ender Dragon will start perching as fast as possible.</td><td style="text-align:center;">OFF</td></tr><tr><td>Disable F3 Screen</td><td>Disables the F3 screen during a match.</td><td style="text-align:center;">OFF</td></tr><tr><td>Disable Copy Location</td><td>Disables F3+C and F3+I during a match to prevent copying the location to the clipboard. For no-calculator runs.</td><td style="text-align:center;">OFF</td></tr><tr><td>Disable F3 Debug Features</td><td>Disables all F3 debug features except for F3+C and F3+I.</td><td style="text-align:center;">OFF</td></tr><tr><td>Disable Forfeit</td><td>Prevents players from forfeiting.</td><td style="text-align:center;">OFF</td></tr><tr><td>Disable Reset</td><td>Prevents players from resetting the world.</td><td style="text-align:center;">OFF</td></tr><tr><td>Icarus Mode</td><td>Starts the match with 1 Elytra and 64 Fireworks.</td><td style="text-align:center;">OFF</td></tr><tr><td>Half-Heart Mode</td><td>Starts the match with only half a heart (1 HP)</td><td style="text-align:center;">OFF</td></tr><tr><td>Hardcore Mode</td><td>The world&#39;s difficulty is fixed to Hard and you will automatically reset the world if you die.</td><td style="text-align:center;">OFF</td></tr><tr><td>Disable Modified Loot Tables</td><td>Disables MCSR Ranked loot table modifications (like Ruined Portals).</td><td style="text-align:center;">OFF</td></tr><tr><td>Replace Zombie Spawner</td><td>Replaces zombie spawner to other mob spawner in the dungeon (spider or skeleton).</td><td style="text-align:center;">ON</td></tr></tbody></table><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>In a Private Room more categories can be chosen than the default Any% Category. Listed below are all the different categories with their explanation.</p><table tabindex="0"><thead><tr><th>Category</th><th>Explanation</th></tr></thead><tbody><tr><td>Any%</td><td>Defeat the Ender Dragon and enter the exit portal in the End Fountain.</td></tr><tr><td>All Advancements</td><td>Complete all 80 Advancements.</td></tr><tr><td>Half%</td><td>Complete any 40 Advancements.</td></tr><tr><td>Quater%</td><td>Complete any 20 Advancements</td></tr><tr><td>All Portals</td><td>Activate all 128 End Portals and enter the exit portal in the End Fountain.</td></tr><tr><td>All Blocks</td><td>Place down all 650 blocks.</td></tr><tr><td>All Bosses</td><td>Defeat the Ender Dragon, Wither and Elder Guardian.</td></tr><tr><td>Kill Wither</td><td>Kill Wither</td></tr><tr><td>Kill Elder Guardian</td><td>Kill Elder Guardian</td></tr><tr><td>How Did We Get Here?</td><td>Obtain the &#39;How Did We Get Here?&#39; Advancement by having every status effect at the same time.</td></tr><tr><td>Hero of the Village</td><td>Obtain the &#39;Hero of the Village&#39; Advancement by defeating a Raid.</td></tr><tr><td>Arbalistic</td><td>Obtain the &#39;Arbalistic&#39; Advancement by killing 5 unique mobs with one Crossbow shot.</td></tr><tr><td>Cover Me in Debris</td><td>Obtain the &#39;Cover Me in Debris&#39; Advancement by wearing a full set of Netherite Armor.</td></tr><tr><td>Enter Nether</td><td>Enter the Nether.</td></tr><tr><td>Etner Edn</td><td>Enter the End.</td></tr><tr><td>Mine a Chunk</td><td>Mine a full chunk (excluding bedrock).</td></tr><tr><td>High%</td><td>Reach the heightlimit.</td></tr><tr><td>All Swords</td><td>Obtain all 6 unique swords.</td></tr><tr><td>All Minerals</td><td>Obtain Coal, Iron Ingot, Gold Ingot, Diamond, Netherite Ingot, Emerald, Lapis Lazuli, Redstone Dust and Nether Quartz.</td></tr><tr><td>Full IA, 15 LVL</td><td>Wear full Iron Armor and get 15 levels.</td></tr><tr><td>All Workstations</td><td>Obtain all 13 workstations.</td></tr><tr><td>Full Inventory</td><td>Have a full inventory of unique items.</td></tr><tr><td>Stack of Lime Wool</td><td>Obtain a stack of Lime Wool.</td></tr></tbody></table>',22)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
